UPDATE COMMENTS
   SET IS_DELETED = 1
 WHERE COMMENT_ID = #{commentNo}
   AND WRITER_NO = #{writerNo}

mapper.delete:
DELETE FROM RECENT_VIEWS
 WHERE USER_NO = #{userNo}
   AND PRODUCT_ID = #{productNo}

DELETE FROM RECENT_VIEWS
 WHERE USER_NO = #{userNo}
   AND VIEW_ID NOT IN (
       SELECT VIEW_ID FROM (
           SELECT VIEW_ID FROM RECENT_VIEWS
            WHERE USER_NO = #{userNo}
            ORDER BY VIEWED_AT DESC
       )
       WHERE ROWNUM <= 30
   )
